"use strict";(globalThis.webpackChunkgrc||=[]).push([[34485],{12159(e){e.exports=JSON.parse('{"citeKey":"zou2022acceleratinggraph","slug":"zou-2022-accelerating-graph-bc19","title":"Accelerating Graph Processing with Lightweight Learning-Based Data Reordering","authors":["M. Zou","M. Zhang","R. Wang","X.-H. Sun","X. Ye","D. Fan","Z. Tang"],"venue":"The IEEE Computer Architecture Letters (CAL\'2022)","type":"Journal","entryType":"article","date":"May, 2022","year":2022,"era":"iit","month":5,"doi":"10.1109/lca.2022.3151087","abstract":"Graph processing is a vital component in various application domains. However, a good graph processing performance is hard to achieve due to its intensive irregular data accesses. Noticing that in real-world graphs, a small portion of vertices occupy most connections, several techniques are proposed to reorder vertices based on their access frequency for better data access locality. However, these approaches can be further improved by identifying reordered data more effectively, which will reduce reordering overhead and improve overall performance. In this letter, we propose Learning-Based Reordering (LBR), a novel lightweight framework that identifies and reorders hot data adaptively for given graphs, algorithms, and threads. Our experimental evaluation indicates that LBR decreases reordering overhead by 24.7% while improves performance by 9.9% compared to the best-performing existing scheme.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2022/zou-2022-accelerating-graph-bc19.pdf"},"_projectIds":["optmem","smc2-planning"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["optmem","smc2-planning"],"memberAuthors":["sun-xian-he"],"funding":[{"agency":"NSF","award":"CCF-2008907","projectId":"optmem"},{"agency":"NSF","award":"CCF-2029014","projectId":"smc2-planning"}]}')}}]);